#!/usr/bin/env node
// Extract the loadable memory image of an ELF binary.
// Usage: node extract.js <binary> > out.json
// Output: JSON object mapping virtual address (decimal string) -> 32-bit
// little/big-endian word value (unsigned integer) for every 4-byte aligned
// word of every PT_LOAD segment's file-backed data.

'use strict';

const fs = require('fs');

function die(msg) {
  process.stderr.write(msg + '\n');
  process.exit(1);
}

const path = process.argv[2];
if (!path) die('usage: node extract.js <elf-binary>');

const buf = fs.readFileSync(path);

if (buf.length < 64 || buf[0] !== 0x7f || buf[1] !== 0x45 || buf[2] !== 0x4c || buf[3] !== 0x46) {
  die('not an ELF file');
}

const is64 = buf[4] === 2;          // EI_CLASS: 1 = ELF32, 2 = ELF64
const little = buf[5] !== 2;        // EI_DATA:  1 = LSB, 2 = MSB

function u16(off) { return little ? buf.readUInt16LE(off) : buf.readUInt16BE(off); }
function u32(off) { return little ? buf.readUInt32LE(off) : buf.readUInt32BE(off); }
function u64(off) {
  const v = little ? buf.readBigUInt64LE(off) : buf.readBigUInt64BE(off);
  return Number(v);
}
function addr(off) { return is64 ? u64(off) : u32(off); }

// ELF header: e_phoff / e_phentsize / e_phnum
const e_phoff = is64 ? u64(0x20) : u32(0x1c);
const e_phentsize = is64 ? u16(0x36) : u16(0x2a);
const e_phnum = is64 ? u16(0x38) : u16(0x2c);

const PT_LOAD = 1;
const mem = new Map();

for (let i = 0; i < e_phnum; i++) {
  const ph = e_phoff + i * e_phentsize;
  if (ph + e_phentsize > buf.length) break;

  const p_type = u32(ph);
  if (p_type !== PT_LOAD) continue;

  let p_offset, p_vaddr, p_filesz;
  if (is64) {
    p_offset = addr(ph + 0x08);
    p_vaddr = addr(ph + 0x10);
    p_filesz = addr(ph + 0x20);
  } else {
    p_offset = addr(ph + 0x04);
    p_vaddr = addr(ph + 0x08);
    p_filesz = addr(ph + 0x10);
  }

  const end = Math.min(p_offset + p_filesz, buf.length);
  for (let off = p_offset, va = p_vaddr; off + 4 <= end; off += 4, va += 4) {
    const val = little ? buf.readUInt32LE(off) : buf.readUInt32BE(off);
    mem.set(va, val);
  }
}

const addrs = Array.from(mem.keys()).sort((a, b) => a - b);
const out = [];
for (const a of addrs) out.push(JSON.stringify(String(a)) + ':' + mem.get(a));
process.stdout.write('{' + out.join(',') + '}\n');

